src/GaleonBrain.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title GaleonBrain
 * @notice On-chain AI Trading Intelligence Layer for Monad
 * @dev Stores AI trade decisions, records AI-Endorsed Trades,
 *      and tracks Micro-Execution positions.
 *      Oracle pushes decisions from off-chain Brain.
 *      Any Monad app can query decisions and trader stats.
 */
contract GaleonBrain {
    address public oracle;
    address public owner;
    address public galeonRouter;

    // ========== Trade Decision ==========
    struct TradeDecision {
        string asset;
        uint8 direction;          // 0=WAIT, 1=LONG, 2=SHORT
        uint8 confidence;         // 0-100
        uint8 riskLevel;          // 0=LOW, 1=MEDIUM, 2=HIGH
        int256 entryPrice;        // 18 decimals
        int256 stopLoss;
        int256 takeProfit;
        string reasoning;
        uint16 similarSetups;
        uint8 historicalWinRate;  // 0-100
        uint256 timestamp;
    }

    // asset hash => latest decision
    mapping(bytes32 => TradeDecision) public latestDecisions;
    // decision history
    mapping(uint256 => TradeDecision) public decisionHistory;
    uint256 public decisionCount;

    // ========== AI-Endorsed Trade ==========
    struct AIEndorsedTrade {
        address trader;
        address token;
        uint256 amount;
        uint8 direction;
        uint8 confidence;
        uint8 riskLevel;
        uint16 similarSetups;
        uint8 historicalWinRate;
        uint256 decisionId;
        uint256 timestamp;
        bool settled;
        int256 pnlBps;           // basis points: +100 = +1%
        uint8 microSteps;        // total micro-execution steps
    }

    mapping(uint256 => AIEndorsedTrade) public endorsedTrades;
    uint256 public endorsedTradeCount;
    mapping(address => uint256[]) public traderHistory;

    // ========== Trader Stats (aggregated) ==========
    struct TraderStats {
        uint256 totalTrades;
        uint256 winCount;
        int256 totalPnlBps;
        uint256 totalMicroSteps;
    }
    mapping(address => TraderStats) public traderStats;

    // ========== Events ==========
    event DecisionPublished(
        string indexed assetIndexed,
        string asset,
        uint8 direction,
        uint8 confidence,
        uint256 decisionId
    );

    event TradeEndorsed(
        address indexed trader,
        address token,
        uint256 amount,
        uint8 confidence,
        uint256 tradeId
    );

    event TradeSettled(
        uint256 indexed tradeId,
        int256 pnlBps,
        uint8 microSteps
    );

    // ========== Constructor ==========
    constructor(address _oracle) {
        owner = msg.sender;
        oracle = _oracle;
    }

    // ========== Modifiers ==========
    modifier onlyOracle() {
        require(msg.sender == oracle, "Only oracle");
        _;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier onlyRouter() {
        require(msg.sender == galeonRouter, "Only router");
        _;
    }

    // ========== Admin ==========
    function setOracle(address _oracle) external onlyOwner {
        oracle = _oracle;
    }

    function setRouter(address _router) external onlyOwner {
        galeonRouter = _router;
    }

    function transferOwnership(address _newOwner) external onlyOwner {
        owner = _newOwner;
    }

    // ========== Oracle: Publish Decision ==========
    function publishDecision(
        string calldata asset,
        uint8 direction,
        uint8 confidence,
        uint8 riskLevel,
        int256 entryPrice,
        int256 stopLoss,
        int256 takeProfit,
        string calldata reasoning,
        uint16 similarSetups,
        uint8 historicalWinRate
    ) external onlyOracle returns (uint256 decisionId) {
        decisionId = decisionCount++;

        TradeDecision memory d = TradeDecision({
            asset: asset,
            direction: direction,
            confidence: confidence,
            riskLevel: riskLevel,
            entryPrice: entryPrice,
            stopLoss: stopLoss,
            takeProfit: takeProfit,
            reasoning: reasoning,
            similarSetups: similarSetups,
            historicalWinRate: historicalWinRate,
            timestamp: block.timestamp
        });

        bytes32 assetHash = keccak256(abi.encodePacked(asset));
        latestDecisions[assetHash] = d;
        decisionHistory[decisionId] = d;

        emit DecisionPublished(asset, asset, direction, confidence, decisionId);
    }

    // ========== Query: Get Latest Decision ==========
    function getTradeDecision(string calldata asset)
        external
        view
        returns (
            uint8 direction,
            uint8 confidence,
            uint8 riskLevel,
            int256 entryPrice,
            int256 stopLoss,
            int256 takeProfit,
            string memory reasoning,
            uint16 similarSetups,
            uint8 historicalWinRate,
            uint256 timestamp
        )
    {
        bytes32 assetHash = keccak256(abi.encodePacked(asset));
        TradeDecision storage d = latestDecisions[assetHash];
        return (
            d.direction,
            d.confidence,
            d.riskLevel,
            d.entryPrice,
            d.stopLoss,
            d.takeProfit,
            d.reasoning,
            d.similarSetups,
            d.historicalWinRate,
            d.timestamp
        );
    }

    // ========== Record AI-Endorsed Trade ==========
    function recordEndorsedTrade(
        address trader,
        address token,
        uint256 amount,
        uint256 decisionId
    ) external onlyRouter returns (uint256 tradeId) {
        TradeDecision storage d = decisionHistory[decisionId];

        tradeId = endorsedTradeCount++;

        endorsedTrades[tradeId] = AIEndorsedTrade({
            trader: trader,
            token: token,
            amount: amount,
            direction: d.direction,
            confidence: d.confidence,
            riskLevel: d.riskLevel,
            similarSetups: d.similarSetups,
            historicalWinRate: d.historicalWinRate,
            decisionId: decisionId,
            timestamp: block.timestamp,
            settled: false,
            pnlBps: 0,
            microSteps: 1
        });

        traderHistory[trader].push(tradeId);
        traderStats[trader].totalTrades++;

        emit TradeEndorsed(trader, token, amount, d.confidence, tradeId);
    }

    // ========== Update Micro-Step Count ==========
    function incrementMicroStep(uint256 tradeId) external onlyRouter {
        endorsedTrades[tradeId].microSteps++;
    }

    // ========== Settle Trade ==========
    function settleTrade(uint256 tradeId, int256 pnlBps) external onlyRouter {
        AIEndorsedTrade storage t = endorsedTrades[tradeId];
        require(!t.settled, "Already settled");

        t.settled = true;
        t.pnlBps = pnlBps;

        TraderStats storage stats = traderStats[t.trader];
        stats.totalPnlBps += pnlBps;
        stats.totalMicroSteps += t.microSteps;
        if (pnlBps > 0) {
            stats.winCount++;
        }

        emit TradeSettled(tradeId, pnlBps, t.microSteps);
    }

    // ========== Query: Trader Stats ==========
    function getTraderFullStats(address trader)
        external
        view
        returns (
            uint256 totalTrades,
            uint256 winCount,
            int256 totalPnlBps,
            uint256 totalMicroSteps,
            uint8 winRate
        )
    {
        TraderStats storage s = traderStats[trader];
        totalTrades = s.totalTrades;
        winCount = s.winCount;
        totalPnlBps = s.totalPnlBps;
        totalMicroSteps = s.totalMicroSteps;
        winRate = totalTrades > 0 ? uint8((winCount * 100) / totalTrades) : 0;
    }

    // ========== Query: Trader Trade Count ==========
    function getTraderTradeCount(address trader) external view returns (uint256) {
        return traderHistory[trader].length;
    }

    // ========== Query: Trader Trade ID by Index ==========
    function getTraderTradeId(address trader, uint256 index) external view returns (uint256) {
        return traderHistory[trader][index];
    }
}

src/GaleonRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "./GaleonBrain.sol";

/**
 * @title GaleonRouter
 * @notice AI Micro-Execution Router for Monad
 * @dev Routes swaps through Kuru DEX, collects 0.5% fee,
 *      records AI-Endorsed Trades, and manages Micro-Execution positions.
 *
 * Micro-Execution: Brain splits every trade into block-by-block micro-steps:
 *   - DCA entry (2-4 steps, confirming price direction)
 *   - Partial take-profit (30%/30%/40% ladder)
 *   - Dynamic stop-loss adjustment
 *   - Emergency exit on risk signal
 */

interface IERC20 {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IKuruRouter {
    function swap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        address recipient
    ) external returns (uint256 amountOut);
}

contract GaleonRouter {
    address public owner;
    GaleonBrain public galeonBrain;
    address public kuruRouter;
    address public feeReceiver;
    uint256 public feeRate = 50; // 0.5% = 50 / 10000

    // ========== Micro-Execution Position ==========
    struct MicroPosition {
        address trader;
        address tokenIn;          // USDC
        address tokenOut;         // target token
        uint256 totalAmountIn;    // cumulative USDC spent
        uint256 totalTokenAmount; // cumulative token received
        uint256 realizedPnl;      // realized PnL from partial exits (in tokenIn)
        uint8 stepCount;
        uint256 decisionId;
        uint256 endorsedTradeId;  // linked GaleonBrain endorsed trade
        bool isOpen;
        uint256 openedAt;
    }

    mapping(uint256 => MicroPosition) public microPositions;
    uint256 public positionCount;

    // trader => active position IDs
    mapping(address => uint256[]) public traderPositions;

    // ========== Events ==========
    event MicroPositionOpened(uint256 indexed positionId, address indexed trader, address token, uint256 amount, uint256 decisionId);
    event MicroStep(uint256 indexed positionId, string stepType, uint256 amountIn, uint256 amountOut, uint8 stepNumber);
    event MicroPositionClosed(uint256 indexed positionId, uint256 totalIn, uint256 totalOut, int256 pnlBps);
    event FeeCollected(address indexed trader, uint256 feeAmount);

    // ========== Constructor ==========
    constructor(
        address _galeonBrain,
        address _kuruRouter,
        address _feeReceiver
    ) {
        owner = msg.sender;
        galeonBrain = GaleonBrain(_galeonBrain);
        kuruRouter = _kuruRouter;
        feeReceiver = _feeReceiver;
    }

    // ========== Modifiers ==========
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    // ========== Admin ==========
    function setFeeRate(uint256 _feeRate) external onlyOwner {
        require(_feeRate <= 100, "Fee too high"); // max 1%
        feeRate = _feeRate;
    }

    function setKuruRouter(address _kuruRouter) external onlyOwner {
        kuruRouter = _kuruRouter;
    }

    function setFeeReceiver(address _feeReceiver) external onlyOwner {
        feeReceiver = _feeReceiver;
    }

    // ========== Fee Calculation ==========
    function _collectFee(address token, uint256 amount) internal returns (uint256 afterFee) {
        uint256 fee = (amount * feeRate) / 10000;
        afterFee = amount - fee;
        if (fee > 0) {
            IERC20(token).transfer(feeReceiver, fee);
            emit FeeCollected(msg.sender, fee);
        }
    }

    // ========== Micro-Execution: Open Position (DCA Step 1) ==========
    function openMicroPosition(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 decisionId
    ) external returns (uint256 positionId) {
        // Transfer tokenIn from trader
        IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        // Collect fee
        uint256 swapAmount = _collectFee(tokenIn, amountIn);

        // Approve and swap via Kuru
        IERC20(tokenIn).approve(kuruRouter, swapAmount);
        uint256 amountOut = IKuruRouter(kuruRouter).swap(
            tokenIn, tokenOut, swapAmount, amountOutMin, address(this)
        );

        // Record endorsed trade in GaleonBrain
        uint256 endorsedTradeId = galeonBrain.recordEndorsedTrade(
            msg.sender, tokenOut, amountIn, decisionId
        );

        // Create micro position
        positionId = positionCount++;
        microPositions[positionId] = MicroPosition({
            trader: msg.sender,
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            totalAmountIn: amountIn,
            totalTokenAmount: amountOut,
            realizedPnl: 0,
            stepCount: 1,
            decisionId: decisionId,
            endorsedTradeId: endorsedTradeId,
            isOpen: true,
            openedAt: block.timestamp
        });

        traderPositions[msg.sender].push(positionId);

        emit MicroPositionOpened(positionId, msg.sender, tokenOut, amountIn, decisionId);
        emit MicroStep(positionId, "DCA_IN", amountIn, amountOut, 1);
    }

    // ========== Micro-Execution: DCA Add (Step 2-N) ==========
    function addToPosition(
        uint256 positionId,
        uint256 amountIn,
        uint256 amountOutMin
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Position closed");
        require(pos.trader == msg.sender, "Not your position");

        // Transfer and fee
        IERC20(pos.tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 swapAmount = _collectFee(pos.tokenIn, amountIn);

        // Swap
        IERC20(pos.tokenIn).approve(kuruRouter, swapAmount);
        uint256 amountOut = IKuruRouter(kuruRouter).swap(
            pos.tokenIn, pos.tokenOut, swapAmount, amountOutMin, address(this)
        );

        // Update position
        pos.totalAmountIn += amountIn;
        pos.totalTokenAmount += amountOut;
        pos.stepCount++;

        // Update Brain micro-step counter
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);

        emit MicroStep(positionId, "DCA_IN", amountIn, amountOut, pos.stepCount);
    }

    // ========== Micro-Execution: Partial Take Profit ==========
    function partialExit(
        uint256 positionId,
        uint256 tokenAmount,
        uint256 amountOutMin
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Position closed");
        require(pos.trader == msg.sender, "Not your position");
        require(tokenAmount <= pos.totalTokenAmount, "Exceeds position");

        // Swap token back to tokenIn
        IERC20(pos.tokenOut).approve(kuruRouter, tokenAmount);
        uint256 amountOut = IKuruRouter(kuruRouter).swap(
            pos.tokenOut, pos.tokenIn, tokenAmount, amountOutMin, address(this)
        );

        // Collect fee from proceeds
        uint256 afterFee = _collectFee(pos.tokenIn, amountOut);

        // Send to trader
        IERC20(pos.tokenIn).transfer(msg.sender, afterFee);

        // Update position
        pos.totalTokenAmount -= tokenAmount;
        pos.realizedPnl += afterFee;
        pos.stepCount++;

        galeonBrain.incrementMicroStep(pos.endorsedTradeId);

        emit MicroStep(positionId, "PARTIAL_TP", tokenAmount, afterFee, pos.stepCount);
    }

    // ========== Micro-Execution: Emergency Exit ==========
    function emergencyExit(
        uint256 positionId,
        uint256 amountOutMin
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Position closed");
        require(pos.trader == msg.sender, "Not your position");

        _closePosition(positionId, amountOutMin, "RISK_EXIT");
    }

    // ========== Micro-Execution: Normal Close ==========
    function closePosition(
        uint256 positionId,
        uint256 amountOutMin
    ) external {
        MicroPosition storage pos = microPositions[positionId];
        require(pos.isOpen, "Position closed");
        require(pos.trader == msg.sender, "Not your position");

        _closePosition(positionId, amountOutMin, "FULL_EXIT");
    }

    // ========== Internal: Close Position ==========
    function _closePosition(
        uint256 positionId,
        uint256 amountOutMin,
        string memory exitType
    ) internal {
        MicroPosition storage pos = microPositions[positionId];
        uint256 remainingTokens = pos.totalTokenAmount;
        uint256 exitProceeds = 0;

        if (remainingTokens > 0) {
            // Swap remaining tokens back
            IERC20(pos.tokenOut).approve(kuruRouter, remainingTokens);
            uint256 amountOut = IKuruRouter(kuruRouter).swap(
                pos.tokenOut, pos.tokenIn, remainingTokens, amountOutMin, address(this)
            );

            // Collect fee
            exitProceeds = _collectFee(pos.tokenIn, amountOut);

            // Send to trader
            IERC20(pos.tokenIn).transfer(msg.sender, exitProceeds);
        }

        // Calculate total PnL in basis points
        uint256 totalOut = pos.realizedPnl + exitProceeds;
        int256 pnlBps = 0;
        if (pos.totalAmountIn > 0) {
            pnlBps = int256((totalOut * 10000) / pos.totalAmountIn) - 10000;
        }

        // Close position
        pos.isOpen = false;
        pos.totalTokenAmount = 0;
        pos.stepCount++;

        // Settle in GaleonBrain
        galeonBrain.incrementMicroStep(pos.endorsedTradeId);
        galeonBrain.settleTrade(pos.endorsedTradeId, pnlBps);

        emit MicroStep(positionId, exitType, remainingTokens, exitProceeds, pos.stepCount);
        emit MicroPositionClosed(positionId, pos.totalAmountIn, totalOut, pnlBps);
    }

    // ========== Simple Swap (non-micro, for manual trades) ==========
    function executeSwap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 decisionId
    ) external returns (uint256 amountOut) {
        IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 swapAmount = _collectFee(tokenIn, amountIn);

        IERC20(tokenIn).approve(kuruRouter, swapAmount);
        amountOut = IKuruRouter(kuruRouter).swap(
            tokenIn, tokenOut, swapAmount, amountOutMin, msg.sender
        );

        // Record AI endorsement
        galeonBrain.recordEndorsedTrade(msg.sender, tokenOut, amountIn, decisionId);
    }

    // ========== Query: Get Active Positions ==========
    function getTraderPositionCount(address trader) external view returns (uint256) {
        return traderPositions[trader].length;
    }

    function getTraderPositionId(address trader, uint256 index) external view returns (uint256) {
        return traderPositions[trader][index];
    }

    // ========== Emergency: Rescue stuck tokens ==========
    function rescueTokens(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }
}

